import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"다중 장부(멀티 Ledger)","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/04-multi-ledger-guide.md","filePath":"v1/ko/guide/04-multi-ledger-guide.md"}'),o={name:"v1/ko/guide/04-multi-ledger-guide.md"};function t(n,a,h,s,d,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="다중-장부-멀티-ledger" tabindex="-1">다중 장부(멀티 Ledger) <a class="header-anchor" href="#다중-장부-멀티-ledger" aria-label="Permalink to &quot;다중 장부(멀티 Ledger)&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>Koala는 여러 장부(ledger)를 만들어 용도별로 내역·카테고리·통계를 분리해 관리할 수 있습니다. 예를 들어 아래처럼 구분해서 쓰기 좋습니다.</p><ul><li>개인</li><li>가족/가계</li><li>여행</li><li>육아</li><li>차량</li><li>리모델링</li><li>비즈니스</li></ul><hr><h2 id="🚀-빠른-시작" tabindex="-1">🚀 빠른 시작 <a class="header-anchor" href="#🚀-빠른-시작" aria-label="Permalink to &quot;🚀 빠른 시작&quot;">​</a></h2><h3 id="새-장부-만들기" tabindex="-1">새 장부 만들기 <a class="header-anchor" href="#새-장부-만들기" aria-label="Permalink to &quot;새 장부 만들기&quot;">​</a></h3><ol><li>Koala 앱을 엽니다</li><li><strong>설정</strong> → <strong>장부 관리</strong></li><li>우측 상단 **+**를 탭합니다</li><li>장부 정보를 입력합니다(이름/설명/아이콘/통화 등)</li><li><strong>저장</strong>을 탭합니다</li></ol><h3 id="장부-전환하기" tabindex="-1">장부 전환하기 <a class="header-anchor" href="#장부-전환하기" aria-label="Permalink to &quot;장부 전환하기&quot;">​</a></h3><ol><li><strong>설정</strong> → <strong>장부 관리</strong></li><li>목록에서 전환할 장부 카드를 탭합니다</li></ol><blockquote><p>📝 참고: 장부를 전환하면 개요/통계/내역 목록 등이 “현재 장부” 기준으로 표시됩니다.</p></blockquote><hr><h2 id="📚-장부-관리" tabindex="-1">📚 장부 관리 <a class="header-anchor" href="#📚-장부-관리" aria-label="Permalink to &quot;📚 장부 관리&quot;">​</a></h2><h3 id="장부-수정" tabindex="-1">장부 수정 <a class="header-anchor" href="#장부-수정" aria-label="Permalink to &quot;장부 수정&quot;">​</a></h3><ol><li><strong>장부 관리</strong>를 엽니다</li><li>장부 카드의 **더보기(… )**를 탭합니다</li><li>장부 상세에서 이름/설명/아이콘/통화 등을 수정합니다</li><li><strong>저장</strong>을 탭합니다</li></ol><h3 id="장부-삭제" tabindex="-1">장부 삭제 <a class="header-anchor" href="#장부-삭제" aria-label="Permalink to &quot;장부 삭제&quot;">​</a></h3><ol><li>장부 상세로 들어갑니다</li><li><strong>장부 삭제</strong>를 탭합니다</li><li>확인 후 삭제합니다</li></ol><blockquote><p>⚠️ 주의:</p><ul><li>삭제하면 해당 장부와 장부 안의 내역이 이 기기에서 제거됩니다.</li><li>클라우드 동기화를 사용 중이라면, 다음 동기화 때 클라우드에도 반영됩니다.</li><li>앱 안에서 복구할 수 없습니다.</li></ul></blockquote><hr><h2 id="💰-장부-통화-기준-통화" tabindex="-1">💰 장부 통화(기준 통화) <a class="header-anchor" href="#💰-장부-통화-기준-통화" aria-label="Permalink to &quot;💰 장부 통화(기준 통화)&quot;">​</a></h2><ul><li>장부마다 통화를 설정할 수 있습니다.</li><li>통화를 바꾸면 표시/통계의 환산 방식이 달라질 수 있습니다.</li></ul><blockquote><p>💡 팁: 통화와 환율에 대해서는 <a href="./05-exchange-rate-guide">환율 안내</a>를 참고하세요.</p></blockquote><hr><h2 id="📊-데이터-분리" tabindex="-1">📊 데이터 분리 <a class="header-anchor" href="#📊-데이터-분리" aria-label="Permalink to &quot;📊 데이터 분리&quot;">​</a></h2><ul><li><strong>내역</strong>: 장부별로 분리</li><li><strong>카테고리</strong>: 장부별로 분리</li><li><strong>태그</strong>: 장부별로 분리</li><li><strong>통계</strong>: 장부별로 분리</li></ul><blockquote><p>📝 참고: <strong>계정(Accounts)은 기기 단위로 공유</strong>되므로, 여러 장부에서 같은 계정을 사용할 수 있습니다.</p></blockquote><hr><h2 id="🔄-동기화-클라우드" tabindex="-1">🔄 동기화(클라우드) <a class="header-anchor" href="#🔄-동기화-클라우드" aria-label="Permalink to &quot;🔄 동기화(클라우드)&quot;">​</a></h2><p>클라우드 동기화를 사용 중이라면 장부도 동기화 대상입니다.</p><ul><li>앱 실행 시</li><li>수동 동기화</li><li>장부 생성/수정/삭제 후 등</li></ul><hr><h2 id="🔧-자주-묻는-질문" tabindex="-1">🔧 자주 묻는 질문 <a class="header-anchor" href="#🔧-자주-묻는-질문" aria-label="Permalink to &quot;🔧 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-장부는-몇-개까지-만들-수-있나요" tabindex="-1">Q1: 장부는 몇 개까지 만들 수 있나요? <a class="header-anchor" href="#q1-장부는-몇-개까지-만들-수-있나요" aria-label="Permalink to &quot;Q1: 장부는 몇 개까지 만들 수 있나요?&quot;">​</a></h3><p>최대 <strong>50개</strong>까지 만들 수 있습니다.</p><h3 id="q2-계정은-장부별인가요" tabindex="-1">Q2: 계정은 장부별인가요? <a class="header-anchor" href="#q2-계정은-장부별인가요" aria-label="Permalink to &quot;Q2: 계정은 장부별인가요?&quot;">​</a></h3><p>아니요. 계정은 기기 단위로 관리되어 모든 장부에서 공유됩니다.</p><hr><p><strong>마지막 업데이트</strong>: 2026년 1월</p>',38)])])}const q=l(o,[["render",t]]);export{g as __pageData,q as default};
